.mpp{max-width:760px;margin:0 auto;font-family:-apple-system,Segoe UI,Roboto,sans-serif;color:#16263F}
.mpp-bar{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1.2rem;flex-wrap:wrap}
.mpp-print{background:#1E3A5F;color:#fff;border:none;border-radius:9px;font-size:1.4rem;font-weight:700;padding:.7rem 1.4rem;cursor:pointer}
.mpp-print:hover{background:#16263F}
.mpp-sheet{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:1.7rem}
.mpp-head{display:flex;justify-content:space-between;align-items:baseline;border-bottom:3px solid #16263F;padding-bottom:.6rem;margin-bottom:1.1rem}
.mpp-head .t{font-size:1.95rem;font-weight:800}
.mpp-head .w{font-size:1.35rem;color:#64748b}
.mpp-head .w input{border:none;border-bottom:1px solid #cbd5e1;font-size:1.35rem;width:140px;text-align:center}
.mpp-sec h4{font-size:1.35rem;font-weight:800;text-transform:uppercase;letter-spacing:.03em;margin:1.2rem 0 .6rem;color:#fff;padding:.35rem .7rem;border-radius:6px}
.mpp-meals h4{background:#2f7d5b}.mpp-groc h4{background:#1E3A5F}.mpp-plan h4{background:#c9902f}
.mpp-mrow{display:flex;align-items:center;gap:.7rem;padding:.4rem 0;border-bottom:1px dotted #d7dde5}
.mpp-mrow .num{width:26px;font-weight:800;color:#94a3b8;font-size:1.3rem;flex:none}
.mpp-mrow input.recipe{flex:1;border:none;border-bottom:1px solid transparent;font-size:1.4rem;padding:.2rem}
.mpp-mrow input.recipe:focus{outline:none;border-bottom-color:#cbd5e1}
.mpp-mrow .svg{width:120px;flex:none}
.mpp-mrow .svg input{width:100%;box-sizing:border-box;border:1px solid #e2e8f0;border-radius:6px;font-size:1.25rem;padding:.3rem .4rem;text-align:center}
.mpp-groc-grid{column-count:2;column-gap:2rem}
@media(max-width:520px){.mpp-groc-grid{column-count:1}}
.mpp-gline{display:flex;align-items:center;gap:.5rem;padding:.32rem 0;break-inside:avoid}
.mpp-gline .box{width:15px;height:15px;border:2px solid #1E3A5F;border-radius:4px;flex:none}
.mpp-gline input{flex:1;border:none;border-bottom:1px solid #e2e8f0;font-size:1.3rem;padding:.15rem}
.mpp-gline input:focus{outline:none;border-bottom-color:#1E3A5F}
